<script lang="ts">
  import { t,locale,formatNumber } from '../lib/i18n';
  import HelpTip from './HelpTip.svelte';
  import type { OutputDisplay, OutputPreview } from '../lib/output-presentation';
  let {profile,disabled=false,displays=[],monitor=false,preview,refreshDisplays=()=>{}}: {profile:any;disabled?:boolean;displays?:OutputDisplay[];monitor?:boolean;preview:(value:OutputPreview)=>void;refreshDisplays?:()=>void}=$props();
  const uid = $props.id();
  function size(event:Event){const value=Number((event.currentTarget as HTMLInputElement).value);preview({botId:profile.id,field:'scale',value});}
  function display(event:Event){const value=(event.currentTarget as HTMLSelectElement).value;preview({botId:profile.id,field:'monitor',value});}
</script>
<label>{$t('Größe')} <span>{formatNumber(Number(profile.avatar.scale),$locale,{maximumFractionDigits:2})}×</span><HelpTip text={$t('Die Figurgröße wird sofort im Studio, Desktop-Overlay und OBS angezeigt. Andere Entwürfe werden dabei nicht gespeichert. Dauerhaft übernehmen mit Änderungen speichern.')}/><input type="range" min="0.3" max="2.5" step="0.05" value={profile.avatar.scale} {disabled} oninput={size} aria-label={$t('Figurgröße live ändern')}/></label>
{#if monitor}<label for={`${uid}-output-monitor`}>{$t('Ausgabemonitor für den Autopiloten')} <HelpTip text={$t('Nur die Darstellung wird auf diesen Monitor erweitert. Diese Auswahl erlaubt keine Bildschirmaufnahme. Ohne Autopilot bleibt die feste Fensterposition erhalten.')}/><select id={`${uid}-output-monitor`} onfocus={refreshDisplays} value={profile.output.desktopMonitorId||''} {disabled} onchange={display}><option value="">{$t('Monitor des Figurenfensters')}</option>{#if profile.output.desktopMonitorId&&!displays.some(item=>item.id===profile.output.desktopMonitorId)}<option value={profile.output.desktopMonitorId} disabled>{$t('Monitor nicht verfügbar')}</option>{/if}{#each displays as item}<option value={item.id}>{item.name} · {item.bounds.width} × {item.bounds.height}</option>{/each}</select></label><p class="field-note">{$t('Beim Wandern reicht das transparente Fenster Mausklicks durch. Stop im Studio, im Tray oder über MCP stellt die feste Fenstergröße und Position wieder her.')}</p>{/if}
